switch (*fmt) {
case 'i': case 'd': case 'u': break;
case 'b': base = 2; if (alt) prefix = "0b"; break;
case 'o': base = 8; if (alt) prefix = "0o"; break;
case 'x': base = 16; if (alt) prefix = "0x"; cas = 1; break;
case 'X': base = 16; if (alt) prefix = "0X"; break;
